nextflow_process {

    name "Test Process RSEQC_JUNCTIONSATURATION"
    script "../main.nf"
    process "RSEQC_JUNCTIONSATURATION"

    tag "modules"
    tag "modules_nfcore"
    tag "rseqc"
    tag "rseqc/junctionsaturation"

    test("sarscov2 paired-end [bam]") {

        when {
            process {
                """
                input[0] = channel.of([
                            [ id:'test', single_end: false ], // meta map
                            file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.pdf[0][1]).name,
                    process.out.rscript,
                    process.out.versions_rseqc
                ).match() }
            )
        }
    }

    test("sarscov2 paired-end [bam] - stub") {

    options "-stub"

        when {
            process {
                """
                input[0] = channel.of([
                            [ id:'test', single_end: false ], // meta map
                            file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai", checkIfExists: true)
                ])
                input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/genome/bed/test.bed12", checkIfExists: true)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

